var _markdown = "\n\n`CPed.h` · 字段 / 方法以头文件为准\n\n逻辑帧改状态；drawing 只读。\n\n## 改血量与护甲 [#改血量与护甲]\n\n<Api name=\"m_fHealth / m_fMaxHealth / m_fArmour\">\n  逻辑帧改。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      float m_fHealth;\n      float m_fMaxHealth;\n      float m_fArmour;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CPed* ped = FindPlayerPed();\n      if (!ped) {\n          return;\n      }\n      ped->m_fHealth = ped->m_fMaxHealth;\n      ped->m_fArmour = 100.0f;\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 给武器与切换 [#给武器与切换]\n\n<Api name=\"GiveWeapon / SetCurrentWeapon / ClearWeapons\">\n  逻辑帧。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void GiveWeapon(eWeaponType weaponType, unsigned int ammo, bool likeUnused);\n      void SetCurrentWeapon(int slot);\n      void SetCurrentWeapon(eWeaponType weaponType);\n      void ClearWeapons();\n      void ClearWeapon(eWeaponType weaponType);\n      CWeapon* GetWeapon(); // 当前槽\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      #include \"eWeaponType.h\"\n\n      ped->GiveWeapon(WEAPONTYPE_M4, 999, true);\n      ped->SetCurrentWeapon(WEAPONTYPE_M4);\n      // ped->ClearWeapons();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 改弹药 [#改弹药]\n\n<Api name=\"GrantAmmo / SetAmmo / DoWeHaveWeaponAvailable\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void GrantAmmo(eWeaponType weaponType, unsigned int ammo);\n      void SetAmmo(eWeaponType weaponType, unsigned int ammo);\n      bool DoWeHaveWeaponAvailable(eWeaponType weaponType);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      if (ped->DoWeHaveWeaponAvailable(WEAPONTYPE_M4)) {\n          ped->GrantAmmo(WEAPONTYPE_M4, 100);\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 判断玩家与所在车 [#判断玩家与所在车]\n\n<Api name=\"IsPlayer / IsAlive / m_pVehicle\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      bool IsPlayer();\n      bool IsAlive();\n      CVehicle* m_pVehicle;\n      // ped flags: bInVehicle\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      if (ped->IsPlayer() && ped->IsAlive() && ped->bInVehicle && ped->m_pVehicle) {\n          CVehicle* v = ped->m_pVehicle;\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 查武器槽与熟练度 [#查武器槽与熟练度]\n\n<Api name=\"GetWeaponSlot / GetWeaponSkill / SetWeaponSkill\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      int GetWeaponSlot(eWeaponType weaponType);\n      char GetWeaponSkill(eWeaponType weaponType);\n      char GetWeaponSkill();\n      void SetWeaponSkill(eWeaponType weaponType, char skill);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      int slot = ped->GetWeaponSlot(WEAPONTYPE_M4);\n      ped->SetWeaponSkill(WEAPONTYPE_M4, 2);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 换 ped 模型 [#换-ped-模型]\n\n<Api name=\"SetModelIndex\">\n  模型须已加载。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void SetModelIndex(unsigned int modelIndex);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CStreaming::RequestModel(modelId, 0x16);\n      CStreaming::LoadAllRequestedModels(false);\n      ped->SetModelIndex(modelId);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 取坐标 [#取坐标]\n\n<Api name=\"GetPosition\">\n  改位置在逻辑帧，别在 drawing。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      CVector GetPosition();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CVector pos = ped->GetPosition();\n      pos.z += 2.0f;\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 取骨骼位置 [#取骨骼位置]\n\n<Api name=\"GetBonePosition / GetTransformedBonePosition\">\n  渲染帧可用；注意 clump 有效。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void GetBonePosition(RwV3d& outPosition, unsigned int boneId, bool updateSkinBones);\n      void GetTransformedBonePosition(RwV3d& inOffsetOutPosn, unsigned int boneId, bool updateSkinBones);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      RwV3d bone{};\n      ped->GetBonePosition(bone, 5, false); // bone id 见引擎/逆向表\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 设置 ped 状态与移动 [#设置-ped-状态与移动]\n\n<Api name=\"SetPedState / SetMoveState\">\n  谨慎改状态，易与任务系统打架。\n\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      void SetPedState(ePedState pedState);\n      void SetMoveState(eMoveState moveState);\n      ePedState m_ePedState;\n      // m_nMoveState, m_nPedType\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // ped->SetPedState(...);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n";
